sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Read the workspace reference from the current maintenance record
    var workspaceRef = current.workspace;

    // Set up a GlideRecord to find and update the related Workspace Options record
    var workspaceGR = new GlideRecord('x_1903615_worksp_0_workspace_options');

    // Use the maintenance ticket's workspace reference to retrieve the related record
    if (!workspaceGR.get(workspaceRef)) {
        gs.warn('Sync Workspace Status on Maintenance Change BR: No related Workspace Options record found for maintenance ticket ' + current.number);
        return;
    }

    // Read the ticket status from the maintenance record
    var ticketStatus = current.getValue('ticket_status');

    // If the ticket is Open, the workspace goes into Under maintenance
    if (ticketStatus == 'open') {
        workspaceGR.setValue('status', 'under_maintenance');
    }
    // If the ticket is Closed, the workspace status should match whatever
    // outcome was chosen on the maintenance ticket (Available or Decommissioned)
    else if (ticketStatus == 'closed') {
        var resultingStatus = current.getValue('workspace_status');

        // Guard: only Available or Decommissioned are valid outcomes on Workspace Options.
        // If the ticket was closed without picking an outcome (still 'in_maintenance'),
        // don't write an invalid value — log a warning instead so it can be caught.
        if (resultingStatus == 'available' || resultingStatus == 'decommissioned') {
            workspaceGR.setValue('status', resultingStatus);
        } else {
            gs.warn('Sync Workspace Status on Maintenance Change BR: Maintenance ticket ' + current.number + ' was closed without a valid workspace status (Available/Decommissioned). Workspace Options record was not updated.');
            return;
        }
    }

    // Save the related workspace record — required in after business rules
    workspaceGR.update();

})(current, previous);
